import{_ as i,o as t,c as n,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Entry 911 | Myriad-Rank Republican Civilizational Charter · Article 10 — Four-Dimensional Assessment of Plane-Sovereign Strong Ones","description":"","frontmatter":{"title":"Entry 911 | Myriad-Rank Republican Civilizational Charter · Article 10 — Four-Dimensional Assessment of Plane-Sovereign Strong Ones","no":911,"module":5,"tags":["Charter","Article 10","Plane-Sovereign Strong Ones","Four-Dimensional Assessment","Virtue-and-Ability"],"related":["17-Plane-Sovereign Strong-One Standards","04-Anti-Predationism Core Thesis","29-Symbiosis-Degree Assessment System"]},"headers":[],"relativePath":"en/0911_模块5-第十条-位面至高强者四维考核.md","filePath":"en/0911_模块5-第十条-位面至高强者四维考核.md"}'),a={name:"en/0911_模块5-第十条-位面至高强者四维考核.md"};function o(r,e,l,u,d,h){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="entry-911-myriad-rank-republican-civilizational-charter-·-article-10-—-four-dimensional-assessment-of-plane-sovereign-strong-ones" tabindex="-1">Entry 911 | Myriad-Rank Republican Civilizational Charter · Article 10 — Four-Dimensional Assessment of Plane-Sovereign Strong Ones <a class="header-anchor" href="#entry-911-myriad-rank-republican-civilizational-charter-·-article-10-—-four-dimensional-assessment-of-plane-sovereign-strong-ones" aria-label="Permalink to &quot;Entry 911 | Myriad-Rank Republican Civilizational Charter · Article 10 — Four-Dimensional Assessment of Plane-Sovereign Strong Ones&quot;">​</a></h1><blockquote><p>Module: Module 5 · Civilization Final-Finalization Canonical Entries | Benchmark base: Documents 17, 04, 29</p></blockquote><h2 id="introduction-sovereign-strong-ones-—-all-four-dimensions-none-may-be-missing" tabindex="-1">Introduction: sovereign strong ones — all four dimensions, none may be missing <a class="header-anchor" href="#introduction-sovereign-strong-ones-—-all-four-dimensions-none-may-be-missing" aria-label="Permalink to &quot;Introduction: sovereign strong ones — all four dimensions, none may be missing&quot;">​</a></h2><p>Article 9 solved &quot;how many strong ones to cultivate&quot;; Article 10 solves &quot;what counts as a qualified strong one.&quot; Plane-sovereign strong ones correspond to Origin Realm and above, Heng Yuan Zhou&#39;s topmost power group. The predatory era&#39;s strong-one standard had only one clause — whoever has the biggest fist is sovereign; charter Article 10 changes it to four-dimensional assessment: Force 40, Heart-nature 25, Contribution 20, Responsibility 15. Force is only the entry ticket; heart-nature is the soul; contribution is value; responsibility is the load-bearing. A cultivator with the biggest fist but evil heart-nature and refusal to bear responsibility is in Heng Yuan Zhou not called a sovereign strong one, but a &quot;high-risk individual.&quot;</p><p>This article is from beginning to end placed under the six top-level axioms — the anti-predation axiom draws the bottom line, the republican axiom of Myriad Races establishes the subject, the collective-ascension axiom sets the direction, the causal self-discipline axiom guards the boundary, the law-first axiom preserves self-consistency; the five together constitute this article&#39;s insurmountable spiritual boundary.</p><p>Together with the previous five axioms, this article is also bound by Axiom 6 · Universal Equal Infinite Law: within the Anchor Symbiotic Civilization all beings inherently possess basic infinite power; the easygoing and layabouts retain a guaranteed basic infinity and will not be eliminated by the times; strivers and Youth Supremes may superimpose more and higher levels of infinity; predation thus fundamentally loses meaning.</p><h2 id="i-jurisprudential-basis" tabindex="-1">I. Jurisprudential Basis <a class="header-anchor" href="#i-jurisprudential-basis" aria-label="Permalink to &quot;I. Jurisprudential Basis&quot;">​</a></h2><p>This article is based on the Plane-Sovereign Strong-One Standards (Document 17). Its jurisprudential core is &quot;the strong one&#39;s responsibility exceeds his rights&quot; (Document 04 core proposition three): the higher the realm, the greater the responsibility to the symbiotic network, not the greater the right to predate. The four-dimensional weight design itself is anti-predation — the heart-nature dimension alone holds 25, contribution and responsibility together 35; although the force dimension holds 40, it is only the basic threshold, and after crossing the force line it is the other three dimensions that truly separate people.</p><h2 id="ii-normative-content-four-dimensions-weights-and-passing-lines" tabindex="-1">II. Normative Content: Four Dimensions&#39; Weights and Passing Lines <a class="header-anchor" href="#ii-normative-content-four-dimensions-weights-and-passing-lines" aria-label="Permalink to &quot;II. Normative Content: Four Dimensions&#39; Weights and Passing Lines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Weight</th><th>Passing Points</th></tr></thead><tbody><tr><td>Force</td><td>40%</td><td>Reaches Origin Realm, stably mobilizes origin force, energy purity 99%+</td></tr><tr><td>Heart-nature</td><td>25%</td><td>Passes ethics review, never predated, does not use predation to save itself under extreme duress</td></tr><tr><td>Contribution</td><td>20%</td><td>Contribution value in civilization&#39;s top 20%, at least one civilizational-level contribution record</td></tr><tr><td>Responsibility</td><td>15%</td><td>Willing and able to bear plane-level public duty, annually investing no less than 30% of time</td></tr></tbody></table><p>All four dimensions must pass to qualify; force passing but heart-nature, contribution, or responsibility failing any one, downgrade to &quot;high-risk individual&quot; under supervision.</p><h2 id="iii-scope" tabindex="-1">III. Scope <a class="header-anchor" href="#iii-scope" aria-label="Permalink to &quot;III. Scope&quot;">​</a></h2><p>This article applies to all cultivators wishing to obtain the formal &quot;plane-sovereign strong one&quot; title and corresponding rights (resource priority, law-participation right, civilizational decision-making right, etc.). The title is not life-long; four dimensions are annually re-reviewed: those whose heart-nature, contribution, and responsibility dimensions continuously decline, title and treatment are synchronously downgraded. This article applies especially strictly to special strong ones such as Lin Hao route and D route — their force dimension is naturally prominent, so assessment focus precisely falls on heart-nature and responsibility.</p><h2 id="iv-consequences-of-violation" tabindex="-1">IV. Consequences of Violation <a class="header-anchor" href="#iv-consequences-of-violation" aria-label="Permalink to &quot;IV. Consequences of Violation&quot;">​</a></h2><p>Forging assessment records, disguising consciousness to pass ethics review, refusing public duty after obtaining the title, using title privileges to actually predate, all constitute unconstitutionality under this article. Consequences: title revoked, relevant rights stripped; those cheating in ethics review have their consciousness deep-scan conclusions re-examined, and if necessary pursued under anti-predation clauses; high-risk individuals refusing transformation face cultivation restrictions and plane isolation.</p><h2 id="v-supervision-mechanism" tabindex="-1">V. Supervision Mechanism <a class="header-anchor" href="#v-supervision-mechanism" aria-label="Permalink to &quot;V. Supervision Mechanism&quot;">​</a></h2><p>This article is executed by Alaya Network + multi-layer supervision: force data comes from network energy monitoring, contribution data from six-category automatic contribution measurement, responsibility data from public-task attendance records; only the heart-nature dimension is independently completed by the Anchor Court&#39;s ethics review committee through four means — historical review, voluntary consciousness deep-scan, situational stress tests, and long-term observation. The four-dimensional data is not subordinate to one another and cross-verified, preventing single-dimension score farming.</p><h2 id="vi-a-genius-sent-back" tabindex="-1">VI. A Genius Sent Back <a class="header-anchor" href="#vi-a-genius-sent-back" aria-label="Permalink to &quot;VI. A Genius Sent Back&quot;">​</a></h2><p>The four-dimensional assessment&#39;s most weighty example is a genius sent back. He scored full marks in force, but in the heart-nature review&#39;s stress test, under extreme duress chose to sacrifice the innocent to save himself. The assessment committee did not accommodate him for his force, but moved him from the sovereign-strong-one roster into high-risk-individual supervision. This send-back declared to all civilization: in Heng Yuan Zhou, no matter how big the fist, it cannot buy the word &quot;qualified.&quot; The heart-nature dimension&#39;s one-vote veto lets all strong ones wanting a shortcut understand — force is the entry ticket; passing it only proves you qualify to take the exam, and what truly decides whether you may become a guardian is whom you are willing to use this force to guard.</p><h2 id="five-core-takeaways" tabindex="-1">Five Core Takeaways <a class="header-anchor" href="#five-core-takeaways" aria-label="Permalink to &quot;Five Core Takeaways&quot;">​</a></h2><ul><li><p><strong>Anti-energy waste</strong>: direct strong-one resources toward &quot;qualified guardians&quot; not &quot;force monsters&quot;; putting an end to using great material for trivial purposes</p></li><li><p><strong>Anti-predation</strong>: the heart-nature dimension directly one-vote-vetoes predatory stance; it is anti-predation&#39;s implementation at the strong-one level</p></li><li><p><strong>Tang-Luo upper-limit comparison</strong>: Tang-Luo-type sovereign strong ones only compare fists; Heng Yuan Zhou&#39;s four-dimensional assessment demands virtue-and-ability, with virtue first</p></li><li><p><strong>Myriad Races full coverage</strong>: each clan&#39;s strong ones are assessed by the same four-dimensional ruler; no clan double standards</p></li><li><p><strong>Hyper-multiverse full openness</strong>: four-dimensional standards are synchronously calibrated as civilization expands, no dual tracks re-set when new systems appear</p></li><li><p><strong>Universal equal infinity</strong>: every being inherently possesses basic infinite power; the easygoing layabouts retain a guaranteed basic infinity and will not be eliminated; strivers and Youth Supremes may superimpose higher-level infinity; predation thus fundamentally loses meaning</p></li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The four-dimensional assessment is Heng Yuan Zhou&#39;s rewrite of the word &quot;sovereign.&quot; True sovereignty is not the person with the greatest force, but the person in whom force, heart-nature, contribution, and responsibility are four-in-one. This standard held, the strong-one group is civilization&#39;s guardian, not the knife hanging above Myriad Ranks&#39; heads.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Related documents: <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/17-位面至高强者标准.html">Entry 17 · Plane-Sovereign Strong-One Standards</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/04-反掠夺主义核心论纲.html">Entry 04 · Anti-Predationism Core Thesis</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/29-共生度评估体系.html">Entry 29 · Symbiosis-Degree Assessment System</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/910_模块5-第九条-20％激活战略.html">Entry 910 · Article 9 20% Activation Strategy</a></li></ul>',25)])])}const g=i(a,[["render",o]]);export{m as __pageData,g as default};
